// The message box and the editable code view: the two places the user types
// something the request is built from.
import { render, screen } from '@solidjs/testing-library';
import { describe, expect, it, vi } from 'vitest';
import ChatComposer from './ChatComposer.jsx';
import CodeView from './CodeView.jsx';

describe('ChatComposer', () => {
  const composerProps = (over = {}) => ({
    userMessage: 'hello',
    onUserMessageChange: vi.fn(),
    loading: false,
    onSend: vi.fn(),
    willRunCode: false,
    ...over,
  });

  it('reports what is typed', () => {
    const onUserMessageChange = vi.fn();
    render(() => <ChatComposer {...composerProps({ onUserMessageChange })} />);

    const textarea = screen.getByLabelText('User message') as HTMLTextAreaElement;
    textarea.value = 'typed';
    textarea.dispatchEvent(new Event('input', { bubbles: true }));

    expect(onUserMessageChange).toHaveBeenCalledWith('typed');
  });

  // Chat convention: Enter sends, Shift+Enter inserts a newline.
  it('sends on Enter but not on Shift+Enter', () => {
    const onSend = vi.fn();
    render(() => <ChatComposer {...composerProps({ onSend })} />);
    const textarea = screen.getByLabelText('User message');

    textarea.dispatchEvent(
      new KeyboardEvent('keydown', { key: 'Enter', shiftKey: true, bubbles: true }),
    );
    expect(onSend).not.toHaveBeenCalled();

    textarea.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
    expect(onSend).toHaveBeenCalledOnce();
  });

  it('does not send an empty message', () => {
    const onSend = vi.fn();
    render(() => <ChatComposer {...composerProps({ userMessage: '   ', onSend })} />);

    screen
      .getByLabelText('User message')
      .dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));

    expect(onSend).not.toHaveBeenCalled();
    expect((screen.getByLabelText('Send message') as HTMLButtonElement).disabled).toBe(true);
  });

  it('does not send while a request is already in flight', () => {
    const onSend = vi.fn();
    const { container } = render(() => (
      <ChatComposer {...composerProps({ loading: true, onSend })} />
    ));

    container
      .querySelector('form')
      ?.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));

    expect(onSend).not.toHaveBeenCalled();
    expect(container.querySelector('.spinner')).not.toBeNull();
  });

  it('submits the form', () => {
    const onSend = vi.fn();
    const { container } = render(() => <ChatComposer {...composerProps({ onSend })} />);

    container
      .querySelector('form')
      ?.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));

    expect(onSend).toHaveBeenCalled();
  });

  it('reads as Run when the edited snippet will drive the request', () => {
    render(() => <ChatComposer {...composerProps({ willRunCode: true })} />);
    expect(screen.getByLabelText('Run code').title).toMatch(/Run edited SDK code/);
  });

  // ChatGPT-style: the box grows with the content, including when a tab switch
  // drops a long message into it.
  it('grows to fit the message', () => {
    const textarea = () => screen.getByLabelText('User message') as HTMLTextAreaElement;
    render(() => <ChatComposer {...composerProps({ userMessage: 'one\ntwo\nthree' })} />);
    expect(textarea().style.height).toMatch(/px$/);
  });
});

describe('CodeView', () => {
  it('renders read-only code with no editor', () => {
    const { container } = render(() => <CodeView code="const a = 1;" language="typescript" />);
    expect(container.querySelector('textarea')).toBeNull();
    expect(container.querySelector('code')?.textContent).toContain('const a = 1;');
  });

  it('reports an edit when it is editable', () => {
    const onChange = vi.fn();
    const { container } = render(() => (
      <CodeView code="const a = 1;" language="typescript" editable onChange={onChange} />
    ));

    const textarea = container.querySelector('textarea')!;
    textarea.value = 'const b = 2;';
    textarea.dispatchEvent(new Event('input', { bubbles: true }));

    expect(onChange).toHaveBeenCalledWith('const b = 2;');
  });

  it('copies the code and confirms', async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText } });
    render(() => <CodeView code="const a = 1;" language="typescript" />);

    screen.getByText('Copy').click();
    await vi.waitFor(() => expect(screen.getByText('Copied')).toBeTruthy());

    expect(writeText).toHaveBeenCalledWith('const a = 1;');
  });

  it('stays quiet when the clipboard is unavailable', async () => {
    Object.defineProperty(navigator, 'clipboard', {
      configurable: true,
      value: { writeText: vi.fn().mockRejectedValue(new Error('denied')) },
    });
    render(() => <CodeView code="const a = 1;" language="typescript" />);

    screen.getByText('Copy').click();
    await Promise.resolve();

    expect(screen.getByText('Copy')).toBeTruthy();
  });

  // Without the pad, the caret on a trailing empty line drifts above the box.
  it('pads a trailing newline so the last line stays visible', () => {
    const { container } = render(() => (
      <CodeView code={'const a = 1;\n'} language="typescript" editable onChange={vi.fn()} />
    ));
    expect(container.querySelector('code')?.textContent?.endsWith(' ')).toBe(true);
  });

  it('mirrors the textarea scroll onto the highlighted layer', () => {
    const { container } = render(() => (
      <CodeView code="const a = 1;" language="typescript" editable onChange={vi.fn()} />
    ));
    const textarea = container.querySelector('textarea')!;
    const pre = container.querySelector('.code-view__pre--bg') as HTMLPreElement;

    textarea.scrollTop = 40;
    textarea.scrollLeft = 12;
    textarea.dispatchEvent(new Event('scroll', { bubbles: true }));

    expect(pre.scrollTop).toBe(40);
    expect(pre.scrollLeft).toBe(12);
  });
});

// Tabs, history and sharing. The tab strip is history entries oldest-first
// followed by drafts, and every action that removes a tab has to leave exactly
// one other tab selected, never a dead response with nothing highlighted.
import { createRoot } from 'solid-js';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createAppState } from './appState';
import { createAppActions } from './appActions';
import { appendHistory, type NewHistoryEntry } from '../services/history';

const fetchMock = vi.fn();

const stored = (over: Partial<NewHistoryEntry> = {}) =>
  appendHistory({
    profileId: 'default',
    profileLabel: 'Default',
    formatId: 'openai-chat',
    formatLabel: 'OpenAI Chat Completions',
    streamed: false,
    url: 'https://gw.example.com/v1/chat/completions',
    baseUrl: 'https://gw.example.com',
    model: 'auto',
    systemPrompt: 'stored prompt',
    userMessage: 'stored message',
    lang: 'bash',
    headers: { 'X-Stored': '1' },
    status: 200,
    statusText: 'OK',
    ok: true,
    durationMs: 10,
    assistantText: 'hi',
    requestBody: '{}',
    requestHeaders: {},
    responseBody: '{}',
    responseHeaders: {},
    responseJson: { choices: [{ message: { content: 'hi' } }] },
    ...over,
  });

function withApp(
  fn: (s: ReturnType<typeof createAppState>, a: ReturnType<typeof createAppActions>) => void,
) {
  createRoot((dispose) => {
    const s = createAppState();
    fn(s, createAppActions(s));
    dispose();
  });
}

beforeEach(() => {
  fetchMock.mockReset();
  fetchMock.mockRejectedValue(new TypeError('Failed to fetch'));
  vi.stubGlobal('fetch', fetchMock);
});

describe('restoring a history entry', () => {
  it('puts the whole request setup and its response back', () => {
    const entry = stored();

    withApp((s, a) => {
      a.restoreFromHistory(entry);

      expect(s.activeHistoryId()).toBe(entry.id);
      expect(s.baseUrl()).toBe('https://gw.example.com');
      expect(s.model()).toBe('auto');
      expect(s.formatId()).toBe('openai-chat');
      expect(s.profile().id).toBe('default');
      expect(s.userMessage()).toBe('stored message');
      expect(s.sentMessage()).toBe('stored message');
      expect(s.systemPrompts().default).toBe('stored prompt');
      expect(s.headerEntries()).toEqual([{ key: 'X-Stored', value: '1' }]);
      expect(s.result()).toMatchObject({ status: 200, ok: true });
    });
  });

  // Entries predate the multi-format work, so the fields it added are optional.
  it('falls back to the defaults for an entry saved before formats existed', () => {
    const entry = stored({ formatId: undefined, url: undefined, streamed: undefined });

    withApp((s, a) => {
      a.restoreFromHistory(entry);
      expect(s.formatId()).toBe('openai-chat');
      expect(s.result()?.url).toBe('https://gw.example.com/v1/chat/completions');
    });
  });

  it('ignores a format id that no longer exists', () => {
    withApp((s, a) => {
      a.restoreFromHistory(stored({ formatId: 'retired-format' }));
      expect(s.formatId()).toBe('openai-chat');
    });
  });

  it('resolves a retired client id through its alias', () => {
    withApp((s, a) => {
      a.restoreFromHistory(stored({ profileId: 'curl' }));
      expect(s.profile().id).toBe('default');
    });
  });

  it('drops a client id that resolves to nothing at all', () => {
    withApp((s, a) => {
      a.restoreFromHistory(stored({ profileId: 'ghost' }));
      expect(s.headerEntries()).not.toEqual([{ key: 'X-Stored', value: '1' }]);
    });
  });

  it('falls back to the client default for a language it cannot use', () => {
    withApp((s, a) => {
      a.restoreFromHistory(stored({ lang: 'rust' }));
      expect(s.lang()).toBe('bash');
    });
  });

  // The provider pill has to agree with the URL it is sitting next to.
  it('re-derives the provider preset from the stored base URL', () => {
    withApp((s, a) => {
      a.restoreFromHistory(stored({ baseUrl: 'https://api.openai.com' }));
      expect(s.provider().id).toBe('openai');
    });
  });

  it('restores the stream toggle when the entry recorded one', () => {
    withApp((s, a) => {
      a.restoreFromHistory(stored({ streamed: true }));
      expect(s.stream()).toBe(true);
    });
  });
});

describe('opening a new request', () => {
  // The common case is firing a second request at the same endpoint.
  it('inherits the setup on screen and starts with an empty message', () => {
    withApp((s, a) => {
      s.selectProvider('anthropic');
      s.setUserMessage('first draft');

      a.handleNewRequest();

      expect(s.drafts()).toHaveLength(2);
      expect(s.userMessage()).toBe('');
      expect(s.provider().id).toBe('anthropic');
    });
  });

  it('parks the message being typed so returning to the tab restores it', () => {
    withApp((s, a) => {
      const first = s.activeDraftId();
      s.setUserMessage('half-written');

      a.handleNewRequest();
      a.selectDraft(first);

      expect(s.userMessage()).toBe('half-written');
    });
  });

  // Without a parked config, retargeting one tab would silently retarget them all.
  it('parks the request setup with the tab, not globally', () => {
    withApp((s, a) => {
      const first = s.activeDraftId();
      s.selectProvider('openai');

      a.handleNewRequest();
      s.selectProvider('anthropic');
      a.selectDraft(first);

      expect(s.provider().id).toBe('openai');
      expect(s.model()).toBe('gpt-4o');
    });
  });

  it('clears the response pane when a draft takes over', () => {
    withApp((s, a) => {
      a.restoreFromHistory(stored());
      expect(s.result()).not.toBeNull();

      a.handleNewRequest();

      expect(s.result()).toBeNull();
      expect(s.hasSent()).toBe(false);
      expect(s.activeHistoryId()).toBeNull();
    });
  });

  it('ignores a request to open a draft that is not there', () => {
    withApp((s, a) => {
      const before = s.activeDraftId();
      a.selectDraft('draft-does-not-exist');
      expect(s.activeDraftId()).toBe(before);
    });
  });
});

// Shared jsdom setup. Wingman is browser-only, so the gaps that matter are the
// browser APIs jsdom does not implement: every one of them is reached by code
// under test, and an unstubbed call throws inside a component and shows up as
// an unrelated render failure.
import { cleanup } from '@solidjs/testing-library';
import { afterEach, beforeEach, vi } from 'vitest';

beforeEach(() => {
  localStorage.clear();
  sessionStorage.clear();
});

afterEach(() => {
  // Explicit, because the library only auto-registers this when Vitest's
  // globals are on and they are not. Without it a rendered App is never
  // disposed: its document-level shortcut listener stays live and the next
  // test's ⌘Enter fires a send from the previous test's component.
  cleanup();
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
  document.body.innerHTML = '';
});

// jsdom implements neither, and both are called from render paths: the request
// tab strip scrolls the active tab into view, and the code panes offer a Copy
// button.
if (!Element.prototype.scrollIntoView) {
  Element.prototype.scrollIntoView = () => {};
}

if (!navigator.clipboard) {
  Object.defineProperty(navigator, 'clipboard', {
    configurable: true,
    value: { writeText: () => Promise.resolve() },
  });
}

// Sending: what goes on the wire, what lands in history, and what happens to
// the draft tab the request was composed in.
import { createRoot } from 'solid-js';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createAppState } from './appState';
import { createAppActions } from './appActions';
import { listHistory } from '../services/history';

const fetchMock = vi.fn();

function reply(body: unknown = { model: 'gpt-4o', choices: [{ message: { content: 'hi' } }] }) {
  return {
    status: 200,
    statusText: 'OK',
    ok: true,
    headers: new Headers({ 'content-type': 'application/json' }),
    text: () => Promise.resolve(JSON.stringify(body)),
    body: null,
  } as unknown as Response;
}

function sseReply(sse: string) {
  const encoder = new TextEncoder();
  return {
    status: 200,
    statusText: 'OK',
    ok: true,
    headers: new Headers({ 'content-type': 'text/event-stream' }),
    text: () => Promise.resolve(sse),
    body: new ReadableStream({
      start(controller) {
        controller.enqueue(encoder.encode(sse));
        controller.close();
      },
    }),
  } as unknown as Response;
}

/** App state + actions, torn down after the callback settles. */
async function withApp(
  fn: (
    s: ReturnType<typeof createAppState>,
    a: ReturnType<typeof createAppActions>,
  ) => Promise<void>,
) {
  let done: Promise<void> = Promise.resolve();
  const dispose = createRoot((disposeRoot) => {
    const s = createAppState();
    done = fn(s, createAppActions(s));
    return disposeRoot;
  });
  await done;
  dispose();
}

/** The POST the send made, ignoring the background health and model probes. */
const sentRequest = () => {
  const call = fetchMock.mock.calls.find(([, init]) => init?.method === 'POST');
  if (!call) throw new Error('no request was sent');
  return { url: call[0] as string, headers: call[1].headers, body: JSON.parse(call[1].body) };
};

beforeEach(() => {
  fetchMock.mockReset();
  fetchMock.mockResolvedValue(reply());
  vi.stubGlobal('fetch', fetchMock);
});

describe('sending from the form', () => {
  it('POSTs the format body to the normalised request URL', async () => {
    await withApp(async (s, a) => {
      s.handleBaseUrlInput('https://gw.example.com/v1');
      s.persistAndSetKey('mnfst_test');
      s.persistAndSetModel('auto');
      s.setUserMessage('hello');

      await a.handleSend();

      expect(sentRequest().url).toBe('https://gw.example.com/v1/chat/completions');
      expect(sentRequest().headers.Authorization).toBe('Bearer mnfst_test');
      expect(sentRequest().body).toEqual({
        model: 'auto',
        messages: [{ role: 'user', content: 'hello' }],
      });
    });
  });

  // The agent profiles exist to be indistinguishable from the real client, so
  // their body fragment has to reach the wire alongside the format's body.
  it("merges the client's body extras over the format body", async () => {
    await withApp(async (s, a) => {
      s.setProfileSafely('openclaw');
      s.setUserMessage('hello');

      await a.handleSend();

      expect(sentRequest().body.max_completion_tokens).toBe(8192);
      expect(sentRequest().body.messages[0].role).toBe('system');
    });
  });

  it('records the result and opens it as a history tab', async () => {
    await withApp(async (s, a) => {
      s.setUserMessage('hello');

      await a.handleSend();

      const [entry] = listHistory();
      expect(entry).toMatchObject({ status: 200, ok: true, userMessage: 'hello' });
      expect(entry?.assistantText).toBe('hi');
      expect(s.activeHistoryId()).toBe(entry?.id);
      expect(s.result()?.ok).toBe(true);
      expect(s.hasSent()).toBe(true);
      expect(s.loading()).toBe(false);
    });
  });

  // A draft that ships becomes a history tab; leaving the empty draft behind
  // would double every request in the strip.
  it('consumes the draft tab the request was composed in', async () => {
    await withApp(async (s, a) => {
      const draftId = s.activeDraftId();
      s.setUserMessage('hello');

      await a.handleSend();

      expect(s.drafts().some((d) => d.id === draftId)).toBe(false);
      expect(s.activeHistoryId()).not.toBeNull();
    });
  });

  it('leaves the drafts alone when re-sending from a history tab', async () => {
    await withApp(async (s, a) => {
      s.setUserMessage('hello');
      await a.handleSend();
      const draftsAfterFirst = s.drafts().length;

      await a.handleSend();

      expect(s.drafts()).toHaveLength(draftsAfterFirst);
      expect(listHistory()).toHaveLength(2);
    });
  });
});

describe('sending refuses an unusable base URL', () => {
  // Left to `fetch`, a schemeless base resolved against Wingman's own origin,
  // quietly shipping the user's API key to a host they never pointed at.
  it('never reaches the network and explains why', async () => {
    await withApp(async (s, a) => {
      s.handleBaseUrlInput('   ');
      s.setUserMessage('hello');

      await a.handleSend();

      expect(fetchMock.mock.calls.some(([, init]) => init?.method === 'POST')).toBe(false);
      expect(s.result()).toMatchObject({
        status: 0,
        statusText: 'Invalid base URL',
        error: 'Base URL is empty.',
      });
      expect(s.loading()).toBe(false);
      expect(listHistory()).toHaveLength(0);
    });
  });

  it('falls back to a generic message when normalisation names no problem', async () => {
    await withApp(async (s, a) => {
      s.handleBaseUrlInput('ftp://gw.example.com');
      s.setUserMessage('hello');
      await a.handleSend();
      expect(s.result()?.error).toMatch(/not a supported scheme/);
    });
  });
});

describe('streaming', () => {
  it('renders the deltas live and stores the assembled reply', async () => {
    fetchMock.mockResolvedValue(
      sseReply(
        'data: {"model":"gpt-4o","choices":[{"delta":{"content":"He"}}]}\n\n' +
          'data: {"choices":[{"delta":{"content":"llo"}}]}\n\n' +
          'data: [DONE]\n\n',
      ),
    );

    await withApp(async (s, a) => {
      s.persistAndSetStream(true);
      s.setUserMessage('hello');

      await a.handleSend();

      expect(s.streamingText()).toBe('Hello');
      expect(s.result()?.isStream).toBe(true);
      expect(listHistory()[0]).toMatchObject({ streamed: true, assistantText: 'Hello' });
    });
  });
});

describe('running the edited snippet instead of the form', () => {
  it('sends what the snippet says, not what the form says', async () => {
    await withApp(async (s, a) => {
      s.setProfileSafely('openai-sdk');
      s.onSdkCodeChange(
        'await new OpenAI({ baseURL: "https://snippet.example.com/v1" }).chat.completions.create({ model: "from-code", messages: [] });',
      );
      s.setUserMessage('hello');
      expect(s.willRunCode()).toBe(true);

      await a.handleSend();

      expect(sentRequest().url).toBe('https://snippet.example.com/v1/chat/completions');
      expect(sentRequest().body.model).toBe('from-code');
      expect(listHistory()[0]?.ok).toBe(true);
    });
  });

  // A snippet that throws is the user's own code failing; it has to read as a
  // result in the response pane, not as an unhandled rejection.
  it('reports a snippet that never calls the SDK as a code error', async () => {
    await withApp(async (s, a) => {
      s.setProfileSafely('openai-sdk');
      s.onSdkCodeChange('const nothing = 1;');
      s.setUserMessage('hello');

      await a.handleSend();

      expect(s.result()).toMatchObject({ status: 0, statusText: 'Code error' });
      expect(s.result()?.error).toMatch(/no request was made/);
    });
  });

  it('stringifies a non-Error thrown by the snippet', async () => {
    await withApp(async (s, a) => {
      s.setProfileSafely('openai-sdk');
      s.onSdkCodeChange('throw "plain string";');
      s.setUserMessage('hello');

      await a.handleSend();

      expect(s.result()?.error).toBe('plain string');
    });
  });
});

describe('a failed request', () => {
  it('records the classified network failure', async () => {
    fetchMock.mockRejectedValue(new TypeError('Failed to fetch'));

    await withApp(async (s, a) => {
      s.setUserMessage('hello');

      await a.handleSend();

      expect(s.result()).toMatchObject({ status: 0, ok: false, errorKind: 'network' });
      expect(listHistory()[0]).toMatchObject({ ok: false, errorMessage: 'Failed to fetch' });
    });
  });
});

// Closing a tab, clearing the strip, and sharing a result. Every action here
// removes something, and each has to leave exactly one other tab selected,
// never a dead response with nothing highlighted.
import { createRoot } from 'solid-js';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createAppState } from './appState';
import { createAppActions } from './appActions';
import { appendHistory, listHistory, type NewHistoryEntry } from '../services/history';

const fetchMock = vi.fn();

const stored = (over: Partial<NewHistoryEntry> = {}) =>
  appendHistory({
    profileId: 'default',
    profileLabel: 'Default',
    formatId: 'openai-chat',
    formatLabel: 'OpenAI Chat Completions',
    streamed: false,
    url: 'https://gw.example.com/v1/chat/completions',
    baseUrl: 'https://gw.example.com',
    model: 'auto',
    systemPrompt: 'stored prompt',
    userMessage: 'stored message',
    lang: 'bash',
    headers: { 'X-Stored': '1' },
    status: 200,
    statusText: 'OK',
    ok: true,
    durationMs: 10,
    assistantText: 'hi',
    requestBody: '{}',
    requestHeaders: {},
    responseBody: '{}',
    responseHeaders: {},
    responseJson: { choices: [{ message: { content: 'hi' } }] },
    ...over,
  });

function withApp(
  fn: (s: ReturnType<typeof createAppState>, a: ReturnType<typeof createAppActions>) => void,
) {
  createRoot((dispose) => {
    const s = createAppState();
    fn(s, createAppActions(s));
    dispose();
  });
}

beforeEach(() => {
  fetchMock.mockReset();
  fetchMock.mockRejectedValue(new TypeError('Failed to fetch'));
  vi.stubGlobal('fetch', fetchMock);
});

describe('closing a tab', () => {
  it('hands over to the tab on the right', () => {
    withApp((s, a) => {
      const first = s.activeDraftId();
      a.handleNewRequest();
      const second = s.activeDraftId();
      a.selectDraft(first);

      a.closeDraft(first);

      expect(s.activeDraftId()).toBe(second);
    });
  });

  it('falls back to the tab on the left when the closed one was last', () => {
    withApp((s, a) => {
      const first = s.activeDraftId();
      a.handleNewRequest();
      const second = s.activeDraftId();

      a.closeDraft(second);

      expect(s.activeDraftId()).toBe(first);
    });
  });

  // Nothing left to fall back to: an empty tab beats a dead response with no
  // tab highlighted.
  it('opens a fresh tab when the last one closes', () => {
    withApp((s, a) => {
      const only = s.activeDraftId();

      a.closeDraft(only);

      expect(s.drafts()).toHaveLength(1);
      expect(s.drafts()[0]?.id).not.toBe(only);
      expect(s.userMessage()).toBe('');
    });
  });

  it('leaves the selection alone when closing a tab that is not open', () => {
    withApp((s, a) => {
      const active = s.activeDraftId();
      a.handleNewRequest();
      const other = s.activeDraftId();
      a.selectDraft(active);

      a.closeDraft(other);

      expect(s.activeDraftId()).toBe(active);
