// The install offer. It has to stay invisible everywhere it can't deliver:
// a browser that never offers, an iOS tab, an already-installed window.
// A dead "Install" is worse than no button at all.
import { render, screen } from '@solidjs/testing-library';
import { afterEach, describe, expect, it, vi } from 'vitest';
import InstallButton from './InstallButton.jsx';
import type { BeforeInstallPromptEvent } from '../services/pwa';

/** Chrome's offer, as the component receives it. */
function offer() {
  const event = new Event('beforeinstallprompt') as BeforeInstallPromptEvent;
  Object.assign(event, {
    prompt: vi.fn().mockResolvedValue(undefined),
    userChoice: Promise.resolve({ outcome: 'accepted' as const, platform: 'web' }),
  });
  return event as BeforeInstallPromptEvent & { prompt: ReturnType<typeof vi.fn> };
}

/** Answer `matchMedia` for the display modes an installed window reports. */
function runningAsApp(installed: boolean) {
  vi.stubGlobal(
    'matchMedia',
    vi.fn((query: string) => ({ matches: installed && query.includes('standalone') })),
  );
}

afterEach(() => {
  Reflect.deleteProperty(navigator, 'standalone');
});

describe('InstallButton', () => {
  it('stays hidden until the browser offers an install', () => {
    runningAsApp(false);
    render(() => <InstallButton />);
    expect(screen.queryByText('Install')).toBeNull();
  });

  it('appears once the offer arrives', () => {
    runningAsApp(false);
    render(() => <InstallButton />);

    window.dispatchEvent(offer());

    expect(screen.getByText('Install')).toBeTruthy();
  });

  // Taking the event over is what suppresses Chrome's own mini-infobar.
  it('takes the offer over from the browser', () => {
    runningAsApp(false);
    render(() => <InstallButton />);
    const event = offer();
    const preventDefault = vi.spyOn(event, 'preventDefault');

    window.dispatchEvent(event);

    expect(preventDefault).toHaveBeenCalled();
  });

  it('prompts on click and spends the offer', async () => {
    runningAsApp(false);
    render(() => <InstallButton />);
    const event = offer();
    window.dispatchEvent(event);

    screen.getByText('Install').click();

    await vi.waitFor(() => expect(event.prompt).toHaveBeenCalledOnce());
    // Single-use: the button goes whether or not the user accepted, and Chrome
    // fires a fresh offer when it decides to ask again.
    expect(screen.queryByText('Install')).toBeNull();
  });

  it('goes away once the app is installed', () => {
    runningAsApp(false);
    render(() => <InstallButton />);
    window.dispatchEvent(offer());
    expect(screen.getByText('Install')).toBeTruthy();

    window.dispatchEvent(new Event('appinstalled'));

    expect(screen.queryByText('Install')).toBeNull();
  });

  // Offering to install the app you are already inside.
  it('stays hidden in an installed window', () => {
    runningAsApp(true);
    render(() => <InstallButton />);

    window.dispatchEvent(offer());

    expect(screen.queryByText('Install')).toBeNull();
  });

  it('stops listening once it unmounts', () => {
    runningAsApp(false);
    const remove = vi.spyOn(window, 'removeEventListener');

    render(() => <InstallButton />).unmount();

    expect(remove).toHaveBeenCalledWith('beforeinstallprompt', expect.any(Function));
    expect(remove).toHaveBeenCalledWith('appinstalled', expect.any(Function));
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { fetchModels } from './models';
import { openaiChat } from '../formats/openai-chat';
import { anthropicMessages } from '../formats/anthropic-messages';

const fetchMock = vi.fn();
const signal = new AbortController().signal;

function catalog(body: unknown, status = 200) {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: () => Promise.resolve(body),
  } as unknown as Response;
}

/** The single request the lookup made. */
function lastCall(): [string, RequestInit] {
  const call = fetchMock.mock.calls[0];
  if (!call) throw new Error('no catalog request was made');
  return call as [string, RequestInit];
}

beforeEach(() => {
  fetchMock.mockReset();
  vi.stubGlobal('fetch', fetchMock);
});

describe('fetchModels', () => {
  it('reads ids out of the OpenAI-shaped catalog', async () => {
    fetchMock.mockResolvedValue(catalog({ data: [{ id: 'auto' }, { id: 'gpt-4o' }] }));
    expect(await fetchModels('https://api.example.com', 'sk-test', openaiChat, signal)).toEqual([
      'auto',
      'gpt-4o',
    ]);
  });

  it('probes the catalog next to the base URL, never doubling a slash', async () => {
    fetchMock.mockResolvedValue(catalog({ data: [] }));
    await fetchModels('https://api.example.com///', '', openaiChat, signal);
    expect(lastCall()[0]).toBe('https://api.example.com/v1/models');
  });

  // Routers put their preferred alias first, so server order is meaningful.
  it('dedupes while keeping server order', async () => {
    fetchMock.mockResolvedValue(catalog({ data: [{ id: 'auto' }, { id: 'a' }, { id: 'auto' }] }));
    expect(await fetchModels('https://x.example.com', '', openaiChat, signal)).toEqual([
      'auto',
      'a',
    ]);
  });

  it('accepts a bare array and plain string entries', async () => {
    fetchMock.mockResolvedValue(catalog(['a', { id: 'b' }]));
    expect(await fetchModels('https://x.example.com', '', openaiChat, signal)).toEqual(['a', 'b']);
  });

  it('skips entries with no usable id', async () => {
    fetchMock.mockResolvedValue(catalog({ data: [{ id: 42 }, { id: '' }, null, { id: 'ok' }] }));
    expect(await fetchModels('https://x.example.com', '', openaiChat, signal)).toEqual(['ok']);
  });

  it('yields nothing for a payload in no recognised shape', async () => {
    fetchMock.mockResolvedValue(catalog({ models: 'nope' }));
    expect(await fetchModels('https://x.example.com', '', openaiChat, signal)).toEqual([]);
  });

  it('sends a bearer token when the format authenticates that way', async () => {
    fetchMock.mockResolvedValue(catalog({ data: [] }));
    await fetchModels('https://x.example.com', 'sk-test', openaiChat, signal);
    expect(lastCall()[1].headers).toMatchObject({ Authorization: 'Bearer sk-test' });
  });

  // Anthropic rejects a browser GET on /v1/models without exactly the same
  // headers /v1/messages needs, so the format's defaults have to come along.
  it("reuses the format's named auth header and default headers", async () => {
    fetchMock.mockResolvedValue(catalog({ data: [] }));
    await fetchModels('https://api.anthropic.com', 'sk-ant', anthropicMessages, signal);
    expect(lastCall()[1].headers).toMatchObject({
      'x-api-key': 'sk-ant',
      'anthropic-version': '2023-06-01',
      'anthropic-dangerous-direct-browser-access': 'true',
    });
  });

  it('sends no credential when the key field is empty', async () => {
    fetchMock.mockResolvedValue(catalog({ data: [] }));
    await fetchModels('https://x.example.com', '', anthropicMessages, signal);
    expect(lastCall()[1].headers).not.toHaveProperty('x-api-key');
  });

  // The lookup is a convenience: plenty of providers 401 or block the browser
  // outright, and the model field has to stay usable as free text regardless.
  it('yields nothing when the endpoint refuses', async () => {
    fetchMock.mockResolvedValue(catalog({}, 401));
    expect(await fetchModels('https://x.example.com', '', openaiChat, signal)).toEqual([]);
  });

  it('yields nothing when the request never lands', async () => {
    fetchMock.mockRejectedValue(new TypeError('Failed to fetch'));
    expect(await fetchModels('https://x.example.com', '', openaiChat, signal)).toEqual([]);
  });

  it('passes the abort signal through so a retarget cancels the lookup', async () => {
    fetchMock.mockResolvedValue(catalog({ data: [] }));
    await fetchModels('https://x.example.com', '', openaiChat, signal);
    expect(lastCall()[1].signal).toBe(signal);
  });
});

import { createEffect, Show, type Component } from 'solid-js';

interface Props {
  userMessage: string;
  onUserMessageChange: (value: string) => void;
  loading: boolean;
  onSend: () => void;
  /** True when Send executes the edited SDK snippet instead of the form. */
  willRunCode: boolean;
}

const SendIcon: Component = () => (
  <svg
    width="14"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    stroke-width="2.4"
    stroke-linecap="round"
    stroke-linejoin="round"
    aria-hidden="true"
  >
    <line x1="12" y1="19" x2="12" y2="5" />
    <polyline points="5 12 12 5 19 12" />
  </svg>
);

/**
 * ChatGPT-style message box: just the text and a send arrow. Everything about
 * the request (client, endpoint, headers, system prompt) is configured in the
 * bars above. This is only what the "user" says.
 */
const ChatComposer: Component<Props> = (props) => {
  let taRef: HTMLTextAreaElement | undefined;

  const canSend = () => !props.loading && props.userMessage.trim().length > 0;

  const onSubmit = (e: SubmitEvent) => {
    e.preventDefault();
    if (canSend()) props.onSend();
  };

  // Grow with the content up to the CSS max-height, ChatGPT-style. Runs on
  // every message change, including programmatic ones (restoring a tab).
  createEffect(() => {
    void props.userMessage;
    if (!taRef) return;
    taRef.style.height = 'auto';
    taRef.style.height = `${Math.min(taRef.scrollHeight, 200)}px`;
  });

  return (
    <form class="chatbox" onSubmit={onSubmit}>
      <div class="chatbox__wrap">
        <textarea
          class="chatbox__textarea"
          ref={taRef}
          rows={1}
          value={props.userMessage}
          onInput={(e) => props.onUserMessageChange(e.currentTarget.value)}
          onKeyDown={(e) => {
            // Enter sends (chat convention); Shift+Enter inserts a newline.
            if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
              e.preventDefault();
              if (canSend()) props.onSend();
            }
          }}
          placeholder="Message the model…"
          spellcheck={true}
          aria-label="User message"
        />
        <button
          type="submit"
          class="chatbox__send"
          classList={{ 'chatbox__send--code': props.willRunCode }}
          disabled={!canSend()}
          title={
            !canSend()
              ? 'Type a message to send'
              : props.willRunCode
                ? 'Run edited SDK code (Enter)'
                : 'Send (Enter)'
          }
          aria-label={props.willRunCode ? 'Run code' : 'Send message'}
        >
          <Show when={props.loading} fallback={<SendIcon />}>
            <span class="spinner spinner--white" />
          </Show>
        </button>
      </div>
    </form>
  );
};

export default ChatComposer;

// Tab, history and sharing actions. Sending lives in sendAction.ts; everything
// here reads and writes through the AppState created in appState.ts.
import { PROFILE_BY_ID, resolveProfileId, type ProfileLang } from '../profiles';
import { FORMATS, FORMAT_BY_ID, DEFAULT_FORMAT_ID, type ApiFormatId } from '../formats';
import { clearHistory, deleteHistory, listHistory, type HistoryEntry } from '../services/history';
import { normalizeBaseUrl } from '../services/baseUrl';
import { buildMarkdownReport } from '../services/gist';
import { STORAGE, entriesFromRecord, providerForBaseUrl, writeStorage } from '../services/settings';
import { newDraftId, tabAfterClosing, type TabRef } from './drafts';
import { createSendAction } from './sendAction';
import type { AppState } from './appState';

export type AppActions = ReturnType<typeof createAppActions>;

export function createAppActions(s: AppState) {
  // The tab strip, left to right: history entries oldest-first, then drafts.
  // Closing a tab needs this order to pick the neighbour to fall back to.
  const tabOrder = (): TabRef[] => [
    ...[...s.history()].reverse().map((e): TabRef => ({ kind: 'history', id: e.id })),
    ...s.drafts().map((d): TabRef => ({ kind: 'draft', id: d.id })),
  ];

  /** Clear the response pane. Every tab switch starts from a blank slate. */
  const clearResponse = () => {
    s.setResult(null);
    s.setStreamingText('');
    s.setSaveStatus('idle');
  };

  const handleSend = createSendAction(s, clearResponse);

  // Park the open draft's message and setup before its tab loses focus, so
  // coming back to it restores what was being typed instead of whatever the
  // tab you visited in between left in the form.
  const parkActiveDraft = () => {
    if (s.activeHistoryId() !== null) return;
    const id = s.activeDraftId();
    const message = s.userMessage();
    const config = s.captureDraftConfig();
    s.setDrafts(s.drafts().map((d) => (d.id === id ? { ...d, message, config } : d)));
  };

  const restoreFromHistory = (entry: HistoryEntry) => {
    parkActiveDraft();
    const restoredProfileId = resolveProfileId(entry.profileId);
    const restoredFormatId: ApiFormatId =
      entry.formatId && FORMAT_BY_ID[entry.formatId]
        ? (entry.formatId as ApiFormatId)
        : DEFAULT_FORMAT_ID;
    s.setFormatId(restoredFormatId);
    writeStorage(STORAGE.format, restoredFormatId);
    s.setProfileId(restoredProfileId);
    writeStorage(STORAGE.profile, restoredProfileId);
    s.persistAndSetBase(entry.baseUrl);
    const restoredProvider = providerForBaseUrl(entry.baseUrl);
    s.setProviderId(restoredProvider);
    writeStorage(STORAGE.provider, restoredProvider);
    s.persistAndSetModel(entry.model);
    if (entry.streamed !== undefined) s.persistAndSetStream(entry.streamed);
    s.setSystemPrompts({ ...s.systemPrompts(), [restoredProfileId]: entry.systemPrompt });
    s.setUserMessage(entry.userMessage);
    s.setSentMessage(entry.userMessage);
    s.setHasSent(true);
    s.setStreamingText('');
    s.setSaveStatus('idle');
    const next = PROFILE_BY_ID[restoredProfileId];
    if (next) {
      const restoredLang = (
        next.langs.includes(entry.lang as ProfileLang) ? entry.lang : next.defaultLang
      ) as ProfileLang;
      s.setLang(restoredLang);
      s.setHeaderOverrides({
        ...s.headerOverrides(),
        [`${restoredFormatId}:${restoredProfileId}:${restoredLang}`]: entriesFromRecord(
          entry.headers,
        ),
      });
    }
    s.setActiveHistoryId(entry.id);
    const fmt = FORMAT_BY_ID[restoredFormatId] ?? FORMATS[0]!;
    s.setResult({
      url: entry.url ?? normalizeBaseUrl(entry.baseUrl, fmt.path).requestUrl,
      status: entry.status,
      statusText: entry.statusText,
      ok: entry.ok,
      durationMs: entry.durationMs,
      requestHeaders: entry.requestHeaders,
      requestBody: entry.requestBody,
      responseHeaders: entry.responseHeaders,
      responseBody: entry.responseBody,
      responseJson: entry.responseJson,
      error: entry.errorMessage,
      isStream: entry.streamed,
    });
  };

  const focusComposer = () => {
    document.querySelector<HTMLTextAreaElement>('.chatbox__textarea')?.focus();
  };

  /** Open a draft tab, restoring the message and setup it was left with. */
  const selectDraft = (id: string) => {
    const draft = s.drafts().find((d) => d.id === id);
    if (!draft) return;
    parkActiveDraft();
    clearResponse();
    s.setActiveHistoryId(null);
    s.setActiveDraftId(id);
    s.setHasSent(false);
    s.setSentMessage('');
    if (draft.config) s.applyDraftConfig(draft.config);
    s.setUserMessage(draft.message);
    focusComposer();
  };

  /**
   * The + button / ⌘⇧O. A new tab inherits the setup you're looking at (the
   * common case is firing a second request at the same endpoint) and starts
   * with an empty message.
   */
  const handleNewRequest = () => {
    const draft = { id: newDraftId(), message: '', config: s.captureDraftConfig() };
    s.setDrafts([...s.drafts(), draft]);
    selectDraft(draft.id);
  };

  /**
   * Activate whatever tab should take over after the active one is closed.
   * `closed` is the tab that just went away, located in the pre-close order.
   */
  const selectAfterClosing = (before: TabRef[], closed: TabRef) => {
    const index = before.findIndex((t) => t.kind === closed.kind && t.id === closed.id);
    const next = index < 0 ? undefined : tabAfterClosing(before, index);
    if (next?.kind === 'draft' && s.drafts().some((d) => d.id === next.id)) {
      selectDraft(next.id);
      return;
    }
    const entry = next?.kind === 'history' ? s.history().find((e) => e.id === next.id) : undefined;
    if (entry) {
      restoreFromHistory(entry);
      return;
    }
    // Nothing left to fall back to, so open an empty tab rather than show a
    // dead response with no tab selected.
    handleNewRequest();
  };

  const closeDraft = (id: string) => {
    const before = tabOrder();
    const wasActive = s.activeHistoryId() === null && s.activeDraftId() === id;
    s.setDrafts(s.drafts().filter((d) => d.id !== id));
    if (wasActive) selectAfterClosing(before, { kind: 'draft', id });
  };

  const handleDelete = (id: string) => {
    const before = tabOrder();
    const wasActive = s.activeHistoryId() === id;
    deleteHistory(id);
    s.setHistory(listHistory());
    if (wasActive) selectAfterClosing(before, { kind: 'history', id });
  };

  const handleClear = () => {
    if (s.history().length === 0) return;
    if (!confirm(`Delete all ${s.history().length} history entries?`)) return;
    const wasOnHistory = s.activeHistoryId() !== null;
    clearHistory();
    s.setHistory([]);
    if (wasOnHistory) {
      const draft = s.drafts()[0];
      if (draft) selectDraft(draft.id);
      else handleNewRequest();
    }
  };

  const handleSaveToGist = () => {
    const r = s.result();
    if (!r) return;
    const markdown = buildMarkdownReport(
      {
        profileLabel: s.profile().label,
        profileCategory: s.profile().category,
        formatLabel: s.format().label,
        streamed: r.isStream ?? false,
        systemPrompt: s.systemPrompts()[s.profile().id] ?? '',
        userMessage: s.sentMessage() || s.userMessage(),
        baseUrl: s.baseUrl(),
        model: s.model(),
        apiKey: s.apiKey(),
      },
      r,
      s.format(),
    );
    s.setGistMarkdown(markdown);
    s.setGistModalOpen(true);
    s.setSaveStatus('saved');
    setTimeout(() => s.setSaveStatus('idle'), 2500);
  };

  return {
    handleSend,
    restoreFromHistory,
    handleDelete,
    handleClear,
    handleNewRequest,
    selectDraft,
    closeDraft,
    focusComposer,
    handleSaveToGist,
  };
}

// Sending a request and recording what came back. Split out of appActions so
// that file stays about tabs and history.
import { sendRequest, sendRequestStreaming, type SendResult } from '../send';
import { appendHistory, listHistory } from '../services/history';
import { runUserCode } from '../runners';
import { recordFromEntries } from '../services/settings';
import type { AppState } from './appState';

export function createSendAction(s: AppState, clearResponse: () => void) {
  const errorResult = (message: string, statusText = 'Code error'): SendResult => ({
    url: s.requestUrl(),
    status: 0,
    statusText,
    ok: false,
    durationMs: 0,
    requestHeaders: {},
    requestBody: '',
    responseHeaders: {},
    responseBody: '',
    responseJson: null,
    error: message,
  });

  return async function handleSend() {
    // A draft that ships is spent: the request it described now exists as a
    // history tab, so the draft tab is consumed rather than left behind empty.
    const sentFromDraft = s.activeHistoryId() === null ? s.activeDraftId() : null;
    clearResponse();
    s.setLoading(true);
    s.setHasSent(true);
    s.setSentMessage(s.userMessage());

    const fmt = s.format();
    let next: SendResult;
    let sentHeaders: Record<string, string>;

    // Stop before `fetch` does. An unusable base URL used to surface either a
    // raw "Failed to parse URL" TypeError or, worse, for a schemeless value, a
    // request resolved against Wingman's own origin, quietly shipping the
    // user's API key somewhere they never pointed at.
    if (!s.normalized().valid) {
      s.setResult(errorResult(s.normalized().problem ?? 'Invalid base URL.', 'Invalid base URL'));
      s.setLoading(false);
      return;
    }

    if (s.willRunCode()) {
      // The user edited the snippet, and this client/language pair can execute
      // it in-browser. Run it through the stub SDK; whatever fetch the code
      // triggers becomes the SendResult.
      try {
        const out = await runUserCode({
          profileId: s.profile().id,
          code: s.sdkCode(),
          baseUrl: s.normalized().base,
          apiKey: s.apiKey(),
        });
        next = out.result;
      } catch (err) {
        next = errorResult(err instanceof Error ? err.message : String(err));
      }
      sentHeaders = next.requestHeaders;
    } else {
      sentHeaders = recordFromEntries(s.headerEntries());
      const p = s.params();
      const body = {
        ...fmt.buildBody(p, { stream: s.stream() }),
        ...(s.profile().bodyExtras?.(p) ?? {}),
      };
      const url = s.requestUrl();
      const input = { url, apiKey: s.apiKey(), auth: fmt.auth, headers: sentHeaders, body };
      next = s.stream()
        ? await sendRequestStreaming(input, {
            createParser: fmt.createStreamParser,
            onDelta: (t) => s.setStreamingText((prev) => prev + t),
          })
        : await sendRequest(input);
    }

    s.setResult(next);
    s.setLoading(false);

    const stored = appendHistory({
      profileId: s.profile().id,
      profileLabel: s.profile().label,
      formatId: fmt.id,
      formatLabel: fmt.label,
      streamed: next.isStream ?? false,
      url: next.url,
      baseUrl: s.baseUrl(),
      model: s.model(),
      systemPrompt: s.systemPrompts()[s.profile().id] ?? '',
      userMessage: s.userMessage(),
      lang: s.lang(),
      headers: sentHeaders,
      status: next.status,
      statusText: next.statusText,
      ok: next.ok,
      durationMs: next.durationMs,
      assistantText: fmt.extractText(next.responseJson) ?? next.streamedText ?? null,
      requestBody: next.requestBody,
      requestHeaders: next.requestHeaders,
      responseBody: next.responseBody,
      responseHeaders: next.responseHeaders,
      responseJson: next.responseJson,
      errorMessage: next.error,
    });
    s.setHistory(listHistory());
    if (sentFromDraft) s.setDrafts(s.drafts().filter((d) => d.id !== sentFromDraft));
    s.setActiveHistoryId(stored.id);
  };
}

