interface Props {
  value: string;
  onChange: (value: string) => void;
  /** Model ids fetched from the endpoint's /v1/models. Empty means unknown. */
  models: string[];
}

const ChevronIcon: Component = () => (
  <svg
    width="10"
    height="10"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    stroke-width="2.4"
    stroke-linecap="round"
    stroke-linejoin="round"
    aria-hidden="true"
  >
    <polyline points="6 9 12 15 18 9" />
  </svg>
);

/**
 * The model field: free-text input first (any id always works), upgraded to a
 * combobox when the endpoint's /v1/models catalog answered. Typing filters;
 * the chevron shows the full list.
 */
const ModelSelect: Component<Props> = (props) => {
  const { open, openMenu: show, close } = createDismissable('.model-select');
  // While the menu is open, typing filters; the chevron shows everything.
  const [filtering, setFiltering] = createSignal(false);

  const filtered = createMemo(() => {
    if (!filtering()) return props.models;
    const q = props.value.trim().toLowerCase();
    if (!q) return props.models;
    return props.models.filter((m) => m.toLowerCase().includes(q));
  });

  const openMenu = (withFilter: boolean) => {
    // Nothing to pick from: the endpoint's catalog was unavailable, so the
    // field stays a plain free-text input.
    if (props.models.length === 0) return;
    setFiltering(withFilter);
    show();
  };

  const handleSelect = (id: string) => {
    props.onChange(id);
    close();
  };

  return (
    <div class="model-select" classList={{ 'model-select--listed': props.models.length > 0 }}>
      <input
        class="model-select__input"
        type="text"
        value={props.value}
        onInput={(e) => {
          props.onChange(e.currentTarget.value);
          openMenu(true);
        }}
        placeholder="model"
        spellcheck={false}
        autocomplete="off"
        aria-label="Model"
        title="Model id sent in the request body"
      />
      <Show when={props.models.length > 0}>
        <button
          type="button"
          class="model-select__toggle"
          onClick={() => (open() ? close() : openMenu(false))}
          aria-haspopup="listbox"
          aria-expanded={open()}
          aria-label="Choose from available models"
          title={`${props.models.length} models reported by this endpoint`}
        >
          <ChevronIcon />
        </button>
      </Show>
      <Show when={open() && filtered().length > 0}>
        <div class="dd-menu model-select__menu" role="listbox" aria-label="Available models">
          <For each={filtered()}>
            {(m) => (
              <button
                type="button"
                class="dd-menu__item model-select__item"
                classList={{ 'dd-menu__item--active': m === props.value }}
                role="option"
                aria-selected={m === props.value}
                onClick={() => handleSelect(m)}
              >
                {m}
              </button>
            )}
          </For>
        </div>
      </Show>
    </div>
  );
};

export default ModelSelect;

// Snippets for the SDK clients. Each one declares the same four things the
// form holds (base URL, key, model, messages) plus any header the user added
// on top of the SDK's own fingerprint, so the panel is a faithful rendering of
// the request and can be read back into the form.
import {
  extraHeaders,
  GENERIC_KEY_PLACEHOLDER,
  indentLines,
  jsonBody,
  keyExpr,
  messages,
  needsOsImport,
  type SnippetContext,
} from './context';

/** `defaultHeaders: { … },` for a JS object literal, or nothing. */
function tsHeaders(ctx: SnippetContext, name = 'defaultHeaders', indent = 2): string {
  const extra = extraHeaders(ctx);
  if (Object.keys(extra).length === 0) return '';
  const pad = ' '.repeat(indent);
  return `\n${pad}${name}: ${indentLines(jsonBody(extra, 2), indent)},`;
}

/** `default_headers={…},` for a Python keyword argument, or nothing. */
function pyHeaders(ctx: SnippetContext, name = 'default_headers', indent = 4): string {
  const extra = extraHeaders(ctx);
  if (Object.keys(extra).length === 0) return '';
  const pad = ' '.repeat(indent);
  return `\n${pad}${name}=${indentLines(jsonBody(extra, 4), indent)},`;
}

/** `import os`, only when the key is a `os.environ[…]` reference. */
function osImport(ctx: SnippetContext): string {
  return needsOsImport(ctx) ? 'import os\n' : '';
}

export function openaiSdkSnippet(ctx: SnippetContext): string {
  const p = ctx.params;
  if (ctx.lang === 'python') {
    return `${osImport(ctx)}from openai import OpenAI

client = OpenAI(
    base_url="${p.baseUrl}/v1",
    api_key=${keyExpr(ctx)},${pyHeaders(ctx)}
)

response = client.chat.completions.create(
    model="${p.model}",
    messages=${indentLines(jsonBody(messages(p), 4), 4)},
)
print(response.choices[0].message.content)`;
  }
  return `import OpenAI from "openai";

const client = new OpenAI({
  baseURL: "${p.baseUrl}/v1",
  apiKey: ${keyExpr(ctx)},${tsHeaders(ctx)}
});

const response = await client.chat.completions.create({
  model: "${p.model}",
  messages: ${indentLines(jsonBody(messages(p), 2), 2)},
});
console.log(response.choices[0].message.content);`;
}

export function vercelSnippet(ctx: SnippetContext): string {
  const p = ctx.params;
  return `import { createOpenAI } from "@ai-sdk/openai";
import { generateText } from "ai";

const manifest = createOpenAI({
  baseURL: "${p.baseUrl}/v1",
  apiKey: ${keyExpr(ctx)},${tsHeaders(ctx, 'headers')}
});

const { text } = await generateText({
  model: manifest("${p.model}"),
  ${p.systemPrompt ? `system: ${JSON.stringify(p.systemPrompt)},\n  ` : ''}prompt: ${JSON.stringify(p.userMessage)},
});
console.log(text);`;
}

export function langchainSnippet(ctx: SnippetContext): string {
