// Model catalog lookup: GET {base}/v1/models, the OpenAI-compatible listing
// endpoint that Manifest, OpenAI, Groq, Mistral (and, same shape, Anthropic)
// all expose. Best-effort: any failure (no CORS, 401, not implemented) simply
// yields an empty list and the model field stays free-text.
import type { ApiFormat } from '../formats';

function modelIdsFrom(json: unknown): string[] {
  const data =
    json && typeof json === 'object' && Array.isArray((json as { data?: unknown }).data)
      ? ((json as { data: unknown[] }).data as unknown[])
      : Array.isArray(json)
        ? (json as unknown[])
        : [];
  const ids: string[] = [];
  for (const entry of data) {
    if (typeof entry === 'string') ids.push(entry);
    else if (entry && typeof entry === 'object') {
      const id = (entry as { id?: unknown }).id;
      if (typeof id === 'string' && id) ids.push(id);
    }
  }
  // Dedupe, keep server order: routers put their preferred alias (auto) first.
  return [...new Set(ids)];
}

export async function fetchModels(
  baseUrl: string,
  apiKey: string,
  format: ApiFormat,
  signal: AbortSignal,
): Promise<string[]> {
  const url = `${baseUrl.replace(/\/+$/, '')}/v1/models`;
  // Reuse the format's auth scheme + default headers (anthropic-version and
  // the direct-browser-access opt-in are required on Anthropic's /v1/models
  // exactly as on /v1/messages).
  const headers: Record<string, string> = { ...(format.defaultHeaders ?? {}) };
  if (format.auth.kind === 'bearer' && apiKey) headers.Authorization = `Bearer ${apiKey}`;
  else if (format.auth.kind === 'header' && apiKey) headers[format.auth.name] = apiKey;
  try {
    const res = await fetch(url, { headers, signal });
    if (!res.ok) return [];
    return modelIdsFrom(await res.json());
  } catch {
    return [];
  }
}

// Snippets for the personal-agent clients. Both configure a CLI rather than
// call an SDK, so they're shell-shaped: the key goes into a config file or a
// `config set` call, not a constructor.
import { envHint, keyInline, type SnippetContext } from './context';

/**
 * OpenClaw's provider config is a single-quoted JSON blob. A hidden key can't
 * just sit inside it (single quotes stop the shell expanding `$VAR`), so the
 * quote is closed around the reference and reopened after it, which is the
 * standard `'…'"$VAR"'…'` splice.
 */
export function openclawSnippet(ctx: SnippetContext): string {
  const p = ctx.params;
  const key = ctx.key.hidden ? `'"$${ctx.key.envName}"'` : keyInline(ctx);
  return `${envHint(ctx)}# OpenClaw routes through its built-in OpenAI-compatible client.
# Configure once with the CLI:
openclaw config set models.providers.manifest '{"baseUrl":"${p.baseUrl}/v1","api":"openai-completions","apiKey":"${key}","models":[{"id":"${p.model}","name":"Manifest Auto"}]}'
openclaw config set agents.defaults.model.primary manifest/${p.model}
openclaw gateway restart`;
}

/**
 * Hermes reads a YAML config. The heredoc is unquoted (`<<EOF`), so the shell
 * expands `$VAR` inside it and a hidden key needs no extra quoting.
 */
export function hermesSnippet(ctx: SnippetContext): string {
  const p = ctx.params;
  return `${envHint(ctx)}# Hermes reads its provider from ~/.hermes/config.yaml:
cat <<EOF > ~/.hermes/config.yaml
model:
  provider: custom
  base_url: ${p.baseUrl}/v1
  api_key: ${keyInline(ctx)}
  default: ${p.model}
EOF
hermes chat -q '${p.userMessage.replace(/'/g, "'\\''")}'`;
}

import { sendRequest } from '../send';
import type { RunnerContext } from './types';

interface VercelOpenAIConfig {
  baseURL?: string;
  apiKey?: string;
  headers?: Record<string, string>;
}

interface VercelModelHandle {
  __config: VercelOpenAIConfig;
  __modelName: string;
}

interface GenerateTextArgs {
  model: VercelModelHandle;
  messages?: Array<{ role: string; content: string }>;
  prompt?: string;
  system?: string;
  [k: string]: unknown;
}

function trimTrailingSlash(url: string): string {
  return url.replace(/\/+$/, '');
}

function extractText(json: unknown): string {
  if (!json || typeof json !== 'object') return '';
  const root = json as Record<string, unknown>;
  const choices = root.choices;
  if (Array.isArray(choices) && choices.length > 0) {
    const first = choices[0] as { message?: { content?: unknown } } | undefined;
    if (typeof first?.message?.content === 'string') return first.message.content;
  }
  return '';
}

/**
 * Stubs `createOpenAI` and `generateText` from the Vercel AI SDK. The
 * generated snippet uses these two named exports. Anything else throws a
 * clear error so users know what's stubbed.
 */
export function makeVercelAIStubs(ctx: RunnerContext) {
  const createOpenAI = (config: VercelOpenAIConfig = {}) => {
    return (modelName: string): VercelModelHandle => ({
      __config: config,
      __modelName: modelName,
    });
  };

  const generateText = async (args: GenerateTextArgs) => {
    const cfg = args.model.__config;
    const baseURL = cfg.baseURL || `${trimTrailingSlash(ctx.defaultBaseUrl)}/v1`;
    const url = `${trimTrailingSlash(baseURL)}/chat/completions`;
    const apiKey = cfg.apiKey || ctx.defaultApiKey;
    const messages: Array<{ role: string; content: string }> = [];
    if (args.system) messages.push({ role: 'system', content: args.system });
    if (Array.isArray(args.messages)) messages.push(...args.messages);
    if (args.prompt) messages.push({ role: 'user', content: args.prompt });
    const body: Record<string, unknown> = {
      model: args.model.__modelName,
      messages,
    };
    const headers: Record<string, string> = {
      'User-Agent': 'ai-sdk/5.0.0 (Node.js v22.17.1)',
      ...(cfg.headers || {}),
    };
    const result = await sendRequest({ url, apiKey, headers, body });
    ctx.hooks.onResult(result);
    if (!result.ok) {
      const err = new Error(
        result.error || `generateText failed: ${result.status} ${result.statusText}`,
      );
      (err as Error & { status?: number }).status = result.status;
      throw err;
    }
    return {
      text: extractText(result.responseJson),
      usage: undefined,
      response: result.responseJson,
    };
  };

  // `streamText` is rarely used in our snippets; surface a clear error if
  // someone tries, which beats a cryptic undefined-call.
  const streamText = async () => {
    throw new Error(
      'streamText is not stubbed in Wingman yet. Switch to generateText to test routing.',
    );
  };

  return { createOpenAI, generateText, streamText };
}

// The entry point. Small, but it is the one file whose failure is a blank page.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const inject = vi.fn();
const render = vi.fn();

vi.mock('@vercel/analytics', () => ({ inject }));
// The bootstrap's job is to find the root and hand it a component; which
// component is App's business, covered in App.test.tsx. Stubbing it also keeps
// the module reset below from loading a second copy of the whole app.
vi.mock('./App.jsx', () => ({ default: () => null }));
vi.mock('solid-js/web', async (importOriginal) => ({
  ...(await importOriginal<typeof import('solid-js/web')>()),
  render,
}));

beforeEach(() => {
  vi.resetModules();
  inject.mockClear();
  render.mockClear();
});

afterEach(() => {
  document.getElementById('root')?.remove();
});

function mountRoot() {
  const root = document.createElement('div');
  root.id = 'root';
  document.body.appendChild(root);
  return root;
}

describe('bootstrap', () => {
  it('renders the app into the root element', async () => {
    const root = mountRoot();

    await import('./index.jsx');

    expect(render).toHaveBeenCalledOnce();
    expect(render.mock.calls[0]?.[1]).toBe(root);
  });

  // A silent no-render is indistinguishable from a broken build; throwing at
  // least says which of the two it is.
  it('throws rather than rendering nowhere', async () => {
    await expect(import('./index.jsx')).rejects.toThrow('Root element not found');
  });

  it('reports analytics as development outside a production build', async () => {
    mountRoot();

    await import('./index.jsx');

    expect(inject).toHaveBeenCalledWith({ mode: 'development' });
  });

  it('reports analytics as production in a production build', async () => {
    mountRoot();
    vi.stubEnv('PROD', true);

    await import('./index.jsx');

    expect(inject).toHaveBeenCalledWith({ mode: 'production' });
  });
});

import { describe, expect, it } from 'vitest';
import { PROVIDERS, PROVIDER_BY_ID, DEFAULT_PROVIDER_ID } from './providers';
import { FORMAT_BY_ID } from './formats';
import { normalizeBaseUrl } from './services/baseUrl';

describe('the provider catalog', () => {
  it('has no duplicate ids', () => {
    expect(new Set(PROVIDERS.map((p) => p.id)).size).toBe(PROVIDERS.length);
  });

  it('names a wire format that exists', () => {
    for (const p of PROVIDERS) {
      expect(FORMAT_BY_ID[p.formatId]).toBeDefined();
    }
  });

  // A preset that carries an endpoint path would double up on the format's own
  // suffix, which is the single most common way to turn a healthy host into a
  // 404. normalizeBaseUrl strips those, so a clean preset survives untouched.
  it('carries a base URL with no endpoint path to strip', () => {
    for (const p of PROVIDERS) {
      if (p.id === DEFAULT_PROVIDER_ID) continue;
      const format = FORMAT_BY_ID[p.formatId]!;
      const normalized = normalizeBaseUrl(p.baseUrl, format.path);
      expect(normalized.valid).toBe(true);
      expect(normalized.base).toBe(p.baseUrl);
      expect(normalized.note).toBeUndefined();
    }
  });

  it('ships a concrete default model for every named provider', () => {
    for (const p of PROVIDERS) {
      expect(p.defaultModel.length).toBeGreaterThan(0);
    }
  });

  it('points every preset at its own logo', () => {
    for (const p of PROVIDERS) {
      expect(p.icon).toMatch(/^\/icons\/providers\/[a-z-]+\.svg$/);
    }
  });
});

describe('Cohere', () => {
  const cohere = PROVIDER_BY_ID['cohere']!;

  // Cohere's OpenAI-compatible surface lives under /compatibility, and the
